$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='D:\projects\cold-prefill-tail-whole-source-r1.json'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
function Run-Git([string[]]$GitArguments){
 $psi=New-Object Diagnostics.ProcessStartInfo
 $psi.FileName='git.exe';$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 $psi.Arguments=($GitArguments|ForEach-Object {'"'+$_.Replace('"','\"')+'"'}) -join ' '
 $p=New-Object Diagnostics.Process;$p.StartInfo=$psi
 if(-not $p.Start()){throw 'Git did not start'}
 $outTask=$p.StandardOutput.ReadToEndAsync();$errTask=$p.StandardError.ReadToEndAsync()
 if(-not $p.WaitForExit(30000)){try{$p.Kill()}catch{};throw 'Git timeout'}
 $stdout=$outTask.GetAwaiter().GetResult();$stderr=$errTask.GetAwaiter().GetResult()
 if($p.ExitCode -ne 0){throw ('Git failed: '+$stderr)}
 return $stdout.Trim()
}

Verify-File $PSCommandPath $m.script_sha256
Verify-File (Join-Path 'D:/projects' $m.build_commands) $m.build_commands_sha256
$bindingPath='D:/projects/cold-prefill-tail-build-dispatch-binding-r1.json'
$binding=[IO.File]::ReadAllText($bindingPath)|ConvertFrom-Json
Verify-File $sourcePath $binding.source_manifest_sha256

$activePath=Join-Path $m.active_run_remote_directory 'run-record.json'
if(-not(Test-Path $activePath)){throw 'Active long run has not completed'}
Verify-File $activePath $binding.completed_active_run_sha256
Verify-File (Join-Path $m.active_run_remote_directory 'launch.json') $m.active_launch_sha256
$active=[IO.File]::ReadAllText($activePath)|ConvertFrom-Json
if(-not $active.host_checks_pass -or @($active.after_processes).Count -ne 0 -or
   -not $active.host.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){
 throw 'Prior long run cleanup or host checks did not pass'
}
foreach($check in $active.host_checks.PSObject.Properties){if(-not $check.Value){throw 'Prior host check failed'}}

$repo=$m.repo.Replace('/','\');$seed=$m.seed.Replace('/','\');$sha=$m.source_commit
$bundle=Join-Path 'D:\projects' $m.bundle;Verify-File $bundle $m.bundle_sha256
if(-not(Test-Path $repo)){
 $null=Run-Git -GitArguments @('-C',$seed,'fetch',$bundle,'HEAD')
 $null=Run-Git -GitArguments @('-C',$seed,'worktree','add','--detach',$repo,$sha)
}
if((Run-Git -GitArguments @('-C',$repo,'rev-parse','HEAD')) -ne $sha -or (Run-Git -GitArguments @('-C',$repo,'status','--porcelain'))){throw 'Source mismatch'}
foreach($item in $m.source_sha256.PSObject.Properties){Verify-File (Join-Path $repo $item.Name) $item.Value}
function Check-Run([string]$Path){
 $r=[IO.File]::ReadAllText($Path)|ConvertFrom-Json
 if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('Incomplete prerequisite '+$Path)}
 return (Get-FileHash $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}
$priorPath=Join-Path $seed $m.prior_completed_run
Verify-File $priorPath $m.prior_completed_run_sha256
$null=Check-Run $priorPath
$build=Join-Path $repo 'build\cold-prefill-tail-whole-provider'
$out=Join-Path $repo 'build\cold-prefill-tail-build-r1';$specPath=$out+'.json'
foreach($p in @($build,$out,$specPath)){if(Test-Path $p){throw 'Evidence exists'}}
$null=New-Item -ItemType Directory -Path (Join-Path $repo 'build') -Force
$inputs=@()
foreach($entry in $m.source_sha256.PSObject.Properties){
 $inputs+=@{file=$entry.Name;sha256=(Get-FileHash (Join-Path $repo $entry.Name) -Algorithm SHA256).Hash.ToLowerInvariant()}
}
$spec=[ordered]@{
 executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path 'D:/projects' $m.build_commands),'-Repo',$repo,'-WholeOut',$build)
 working_directory=$repo;repo_commit=$sha;source_inputs=$inputs
 command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;source_manifest_sha256=(Get-FileHash $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant()
 model='none; native whole-provider compile';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false
 purpose='Compile the cold-tail whole provider, changed C product CLI and prefix delivery/cancellation probe. Native MTP dispatch remains opt-in; no build qualifies inference or performance.'
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds 660|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native build or host check failed'}
$meta=[IO.File]::ReadAllText((Join-Path $build 'build-provenance.json'))|ConvertFrom-Json
if($meta.repo_commit -ne $sha -or $meta.dirty_tree -or -not $meta.sm121_dpp_reduction -or -not $meta.sm121_compact_normalize -or $meta.hawkeye_replay_lanes -ne 4){throw 'Build configuration mismatch'}
if($meta.source_sha256 -ne $m.source_sha256.'native/providers/whole_provider.cpp' -or $meta.hawkeye_dispatch_policy_sha256 -ne $m.source_sha256.'native/providers/hawkeye_dispatch_policy.h'){throw 'Compiled source mismatch'}

if($meta.hawkeye_completed_latency_is_runtime_failure -or -not $meta.hawkeye_completion_requires_stream_sync -or $meta.hawkeye_nominal_dispatch_ms -ne 100 -or $meta.hawkeye_nominal_device_window_ms -ne 250 -or $meta.hawkeye_nominal_matrix_window_ms -ne 250 -or $meta.hawkeye_nominal_correction_ms -ne 10000){throw 'Completed projection latency metadata mismatch'}

if($meta.prefill_chunks_header_sha256 -ne $m.source_sha256.'native/providers/prefill_chunks.h'){throw 'Compiled chunk owner source mismatch'}

$cliMeta=[IO.File]::ReadAllText((Join-Path $repo 'build/prefix-stream-probe/build-provenance.json'))|ConvertFrom-Json
if($cliMeta.repo_commit -ne $sha -or $cliMeta.dirty_tree -or -not $cliMeta.prefix_stream_probe -or $cliMeta.stack_reserve_bytes -ne 268435456){throw 'Probe build configuration mismatch'}
Verify-File $cliMeta.executable $cliMeta.executable_sha256
foreach($entry in $cliMeta.sources){
 Verify-File $entry.path $entry.sha256
 $relative=$entry.path.Substring($repo.Length+1).Replace('\','/')
 if($m.source_sha256.$relative -ne $entry.sha256){throw 'Probe build source mismatch'}
}

$productMeta=[IO.File]::ReadAllText((Join-Path $repo 'build/product-cli/build-provenance.json'))|ConvertFrom-Json
if($productMeta.repo_commit -ne $sha -or $productMeta.dirty_tree -or $productMeta.prefix_stream_probe -or $productMeta.stack_reserve_bytes -ne 268435456){throw 'Product CLI build configuration mismatch'}
Verify-File $productMeta.executable $productMeta.executable_sha256
foreach($entry in $productMeta.sources){
 Verify-File $entry.path $entry.sha256
 $relative=$entry.path.Substring($repo.Length+1).Replace('\','/')
 if($m.source_sha256.$relative -ne $entry.sha256){throw 'Product CLI build source mismatch'}
}

param([Parameter(Mandatory=$true)][ValidateSet('q7169-out32','q8192-out512','q8191-out32','q8193-out32','draft-limit-q262142-out16','draft-limit-q262140-out16','draft-limit-q262143-out16')][string]$Case)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
function Check-Run([string]$Path,[string]$Sha,[bool]$Success){
 Verify-File $Path $Sha;$r=[IO.File]::ReadAllText($Path)|ConvertFrom-Json
 if(-not $r.host.Equals('baiying',[StringComparison]::OrdinalIgnoreCase) -or -not $r.host_checks_pass -or @($r.after_processes).Count){throw 'Host cleanup failed'}
 foreach($check in $r.host_checks.PSObject.Properties){if(-not $check.Value){throw 'Host check failed'}}
 if($Success -and ($r.reason -ne 'completed' -or $r.exit_code -ne 0)){throw 'Required successful run failed'}
}
$sourcePath='D:/projects/cold-tail-native-mtp-source-r1.json';$bindingPath=('D:/projects/cold-tail-native-mtp-'+$Case+'-binding-r1.json')
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json;$binding=[IO.File]::ReadAllText($bindingPath)|ConvertFrom-Json
Verify-File $sourcePath $binding.source_manifest_sha256;Verify-File $PSCommandPath $m.script_sha256
Check-Run (Join-Path $m.active_remote_directory 'run-record.json') $binding.active_run_sha256 $false
Verify-File (Join-Path $m.active_remote_directory 'launch.json') $m.active_launch_sha256
Verify-File $binding.active_boundary_remote $binding.active_boundary_sha256
$activeBoundary=[IO.File]::ReadAllText($binding.active_boundary_remote)|ConvertFrom-Json
# This short independent diagnostic requires resolved host state, not long-context success.
$buildSourcePath=Join-Path 'D:/projects' $m.build_source_manifest
Verify-File $buildSourcePath $m.build_source_manifest_sha256
$buildSource=[IO.File]::ReadAllText($buildSourcePath)|ConvertFrom-Json
$repo=$buildSource.repo;$build=$binding.build
if($build.source_commit -ne $m.source_commit -or $build.source_manifest_sha256 -ne $m.build_source_manifest_sha256){throw 'Build binding mismatch'}
Check-Run (Join-Path $repo ('build/'+$build.run_directory+'/run-record.json')) $build.run_sha256 $true
foreach($entry in $buildSource.source_sha256.PSObject.Properties){Verify-File (Join-Path $repo $entry.Name) $entry.Value}
$wholeDir=Join-Path $repo 'build/cold-prefill-tail-whole-provider';$probeDir=Join-Path $repo 'build/prefix-stream-probe'
Verify-File (Join-Path $wholeDir 'build-provenance.json') $build.whole_metadata_sha256
Verify-File (Join-Path $probeDir 'build-provenance.json') $build.probe_metadata_sha256
foreach($artifact in $build.whole_artifacts){Verify-File (Join-Path $wholeDir $artifact.name) $artifact.sha256}
$provider=Join-Path $wholeDir 'qrt_qwen36_whole_provider.dll';$cli=Join-Path $probeDir 'qrt-prefix-stream-probe.exe'
Verify-File $provider $build.whole_artifact.sha256;Verify-File $cli $build.probe_executable_sha256
Check-Run $m.control_run_remote_path $m.control_run_sha256 $true
foreach($entry in $m.dependency_files){Verify-File $entry.path $entry.sha256}
Verify-File $m.runtime_manifest $m.runtime_manifest_sha256
$runtimeManifest=[IO.File]::ReadAllText($m.runtime_manifest)|ConvertFrom-Json
if($runtimeManifest.dirty_tree -or $runtimeManifest.artifacts.Count -ne 268){throw 'Runtime inventory mismatch'}
foreach($entry in $runtimeManifest.artifacts){
 $path=Join-Path $m.runtime_directory $entry.path;Verify-File $path $entry.sha256
 if((Get-Item -LiteralPath $path).Length -ne $entry.bytes){throw 'Runtime artifact size mismatch'}
}
Verify-File $m.reference_data.manifest_path $m.reference_data.manifest_sha256
foreach($entry in $m.reference_data.files){Verify-File $entry.path $entry.sha256}
$runtimeEnvPath=Join-Path 'D:/projects' $m.profile;Verify-File $runtimeEnvPath $m.profile_sha256

foreach($required in $binding.native_prerequisites){
 Verify-File $required.comparison_remote $required.comparison_sha256
 $qualified=[IO.File]::ReadAllText($required.comparison_remote)|ConvertFrom-Json
 if(-not $qualified.all_bit_exact -or -not $qualified.all_host_guards_pass -or $qualified.source_commit -ne $required.source_commit -or $qualified.manifest_sha256 -ne $required.manifest_sha256){throw 'Native component qualification mismatch'}
 foreach($record in $required.run_records){Check-Run $record.path $record.sha256 $true}
}
if(@($binding.native_prerequisites).Count -ne 3){throw 'Missing native component qualifications'}
foreach($control in $binding.short_controls){
 Check-Run $control.run_path $control.run_sha256 $true
 Verify-File $control.analysis_remote $control.analysis_sha256
 $qualified=[IO.File]::ReadAllText($control.analysis_remote)|ConvertFrom-Json
 if(-not $qualified.qualified -or $qualified.source_commit -ne $m.source_commit -or $qualified.build.whole_artifact.sha256 -ne $build.whole_artifact.sha256){throw 'Short native model qualification mismatch'}
}
if($m.plain_cli.source_commit -ne $m.source_commit -or $m.plain_cli.sha256 -ne $build.cli_executable_sha256 -or $m.plain_cli.path -ne $build.cli_path){throw 'Current C product CLI is required'}
Verify-File $m.plain_cli.path $m.plain_cli.sha256
Verify-File $m.plain_cli.metadata_path $m.plain_cli.metadata_sha256
Check-Run $m.plain_cli.run_path $m.plain_cli.run_sha256 $true
$cases=@($m.cases|Where-Object{$_.name -eq $Case});if($cases.Count -ne 1){throw 'Unknown case'};$c=$cases[0]
if($c.retirement_required){
 if(@($binding.short_controls).Count -ne 4){throw 'All four actual same-source native short controls are required'}
}else{
 if(@($binding.short_controls).Count){throw 'Unexpected control recursion'}
}
$cli=$m.plain_cli.path
$probeArguments=@('run','--model','D:\models\Qwen3.6-35B-A3B','--tokens',$c.prompt,'--output-tokens',([string]$c.outputs),
 '--expected-output',$c.expected,'--expected-prompt-fnv',$c.prompt_fnv1a64,'--expected-output-fnv',$c.output_fnv1a64,
 '--env-file',$runtimeEnvPath,'--provider-dll',$provider,'--ignore-eos')
$timeoutSeconds=[int]$c.native_timeout_seconds
$guard=Join-Path 'D:/projects' $m.guard.file;Verify-File $guard $m.guard.sha256

$out=Join-Path $repo ('build/cold-tail-native-mtp-'+$Case+'-r1');$specPath=$out+'.json'
foreach($path in @($out,$specPath)){if(Test-Path $path){throw 'Evidence exists'}}
$spec=[ordered]@{
 executable=$cli;working_directory=$repo;repo_commit=$m.source_commit
 arguments=$probeArguments
 model='D:\models\Qwen3.6-35B-A3B';model_loaded=$true;batch_size=1
 command_file=$PSCommandPath;command_file_sha256=$m.script_sha256
 source_manifest_sha256=$binding.source_manifest_sha256;build=$build;case=$Case;native_prerequisites=$binding.native_prerequisites;short_controls=$binding.short_controls;plain_cli=$m.plain_cli
 active_boundary_sha256=$binding.active_boundary_sha256;active_run_sha256=$binding.active_run_sha256
 source_inputs=@($buildSource.source_sha256.PSObject.Properties|ForEach-Object{@{file=$_.Name;sha256=$_.Value}})
 reference_data=$m.reference_data;dependency_files=$m.dependency_files;original_case=$c;original_contract=$m.original_contract
 guard_file=$guard;guard_sha256=$m.guard.sha256
 runtime_manifest=$m.runtime_manifest;runtime_manifest_sha256=$m.runtime_manifest_sha256
 environment_sha256=$m.profile_sha256;environment_overrides=$m.profile_overrides
 control_run_sha256=$m.control_run_sha256;control_profile_sha256=$m.control_profile_sha256
 native_mtp_decode_enabled=$true;original_model=$true;quantized=$false;reference_activations_used=$false
 performance_acceptance=$false;release_qualified=$false;diagnostic_timing_only=$true
 purpose='Original GB10 short native MTP controls and actual drafter retirement, using the repaired whole provider and C product CLI from one source revision. All real prompt/output IDs, comparable logits, live callbacks, actual cold chunks, native commits and host cleanup remain required.'
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false))
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
& $guard -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeoutSeconds|Out-Null
Copy-Item -LiteralPath $runtimeEnvPath -Destination (Join-Path $out 'runtime.env')
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks_pass|ConvertTo-Json -Compress
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Prefix streaming probe or host guard failed'}
